function _removeWire(wireId) {
  const e = _wires.get(wireId); if (!e) return;
  e.sub?.();
  e.path?.remove();
  e.observer?.disconnect();
  KERNEL.wireRegistry.remove(wireId);
  _wires.delete(wireId);
  KERNEL.bus.publish('kernel:notify', { message: '✂ Wire removed' });
}

